INSERT INTO `ayuda_articulo` VALUES (1,1,'┬┐C├│mo reservo una cancha?','Busca un espacio en la secci├│n Canchas, elige la cancha y la fecha, selecciona una franja disponible y confirma la reserva. Si es tu primera vez, deber├ís iniciar sesi├│n o crear una cuenta.',1,'ACTIVO','2026-10-18 18:40:01.471986'),(2,1,'┬┐Puedo cancelar o reprogramar mi reserva?','S├¡. Desde Mis reservas puedes cancelar mientras la reserva est├® pendiente o confirmada y la franja lo permita. La reprogramaci├│n est├í disponible para reservas propias dentro del plazo permitido.',2,'ACTIVO','2026-10-18 18:40:01.471986'),(3,1,'┬┐Qu├® pasa si el propietario rechaza mi reserva?','La reserva cambia a RECHAZADA, la franja se libera y, si ya hab├¡as pagado, se registra el reembolso simulado. Puedes reservar otra franja o cancha.',3,'ACTIVO','2026-10-18 18:40:01.471986'),(4,2,'┬┐C├│mo funciona el pago?','El pago es simulado: eliges un medio de pago de demostraci├│n y la plataforma registra el cobro. No se realiza ning├║n cargo real.',1,'ACTIVO','2026-10-18 18:40:01.471986'),(5,2,'┬┐Cu├índo recibo un reembolso?','Cuando una reserva pagada se cancela o es rechazada, el sistema genera un reembolso simulado por el monto correspondiente y lo muestra en el detalle de la reserva.',2,'ACTIVO','2026-10-18 18:40:01.471986'),(6,2,'┬┐Los montos incluyen comisi├│n?','El precio de la cancha y los extras se muestran antes de confirmar. La comisi├│n de plataforma se calcula en las liquidaciones del propietario, no se suma al precio publicado.',3,'ACTIVO','2026-10-18 18:40:01.471986'),(7,3,'┬┐C├│mo creo una cuenta?','Usa el bot├│n Mi cuenta y elige Crear cuenta. Necesitas nombres, apellidos, correo, tel├®fono y una contrase├▒a. Despu├®s podr├ís verificar tu correo e iniciar sesi├│n.',1,'ACTIVO','2026-10-18 18:40:01.471986'),(8,3,'Olvid├® mi contrase├▒a, ┬┐qu├® hago?','En la pantalla de ingreso usa Recuperar contrase├▒a. Recibir├ís un enlace o c├│digo para definir una nueva clave.',2,'ACTIVO','2026-10-18 18:40:01.471986'),(9,3,'┬┐C├│mo me convierto en propietario?','Desde Mi perfil env├¡a tu solicitud de propietario con tu documento de identidad. Un administrador la valida y, al aprobarla, podr├ís publicar tu establecimiento y tus canchas.',3,'ACTIVO','2026-10-18 18:40:01.471986'),(10,4,'┬┐C├│mo me inscribo a una actividad?','Ingresa a Actividades, elige el torneo, clase o partido abierto y pulsa Inscribirme. Debes tener sesi├│n iniciada y quedar├ín cupos disponibles.',1,'ACTIVO','2026-10-18 18:40:01.471986'),(11,4,'┬┐Puedo cancelar mi inscripci├│n?','S├¡, desde Mis inscripciones o desde la misma tarjeta de la actividad. El cupo vuelve a quedar disponible para otros usuarios.',2,'ACTIVO','2026-10-18 18:40:01.471986'),(12,4,'┬┐Qu├® pasa si se cancela la actividad?','Todas las inscripciones pasan a estado CANCELADA y la actividad deja de mostrarse en el listado p├║blico.',3,'ACTIVO','2026-10-18 18:40:01.471986'),(13,5,'┬┐D├│nde ingreso un cup├│n?','Al confirmar una reserva, escribe el c├│digo en el campo de cup├│n o promoci├│n. El descuento se aplica al monto de la cancha antes del pago.',1,'ACTIVO','2026-10-18 18:40:01.471986'),(14,5,'┬┐Por qu├® mi cup├│n no aplica?','El cup├│n debe estar activo, vigente para la fecha de la reserva, asociado a la cancha y con usos disponibles. Si ya lo usaste o se agotaron los canjes, la plataforma mostrar├í un conflicto.',2,'ACTIVO','2026-10-18 18:40:01.471986');
/*!40000 ALTER TABLE `ayuda_articulo` ENABLE KEYS */;
UNLOCK TABLES;

