DROP TABLE IF EXISTS `reserva`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reserva` (
  `id_reserva` bigint NOT NULL AUTO_INCREMENT,
  `id_usuario` int NOT NULL,
  `id_cancha` int NOT NULL,
  `id_promocion` int DEFAULT NULL,
  `inicio` datetime(6) NOT NULL,
  `fin` datetime(6) NOT NULL,
  `monto_cancha` decimal(10,2) NOT NULL,
  `monto_descuento` decimal(10,2) NOT NULL DEFAULT '0.00',
  `estado` varchar(20) NOT NULL DEFAULT 'PENDIENTE',
  `fecha_creacion` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clave_idempotencia` varchar(80) DEFAULT NULL,
  PRIMARY KEY (`id_reserva`),
  UNIQUE KEY `uq_reserva_idempotencia` (`id_usuario`,`clave_idempotencia`),
  KEY `fk_reserva_promocion` (`id_promocion`),
  KEY `ix_reserva_cancha_inicio` (`id_cancha`,`inicio`,`fin`),
  KEY `ix_reserva_usuario_fecha` (`id_usuario`,`fecha_creacion`),
  KEY `ix_reserva_estado_inicio` (`estado`,`inicio`,`fin`),
  CONSTRAINT `fk_reserva_cancha` FOREIGN KEY (`id_cancha`) REFERENCES `cancha` (`id_cancha`),
  CONSTRAINT `fk_reserva_promocion` FOREIGN KEY (`id_promocion`) REFERENCES `promocion` (`id_promocion`),
  CONSTRAINT `fk_reserva_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`),
  CONSTRAINT `ck_reserva_estado` CHECK ((`estado` in (_utf8mb4'PENDIENTE',_utf8mb4'CONFIRMADA',_utf8mb4'CANCELADA',_utf8mb4'RECHAZADA',_utf8mb4'EXPIRADA',_utf8mb4'FINALIZADA'))),
  CONSTRAINT `ck_reserva_montos` CHECK (((`monto_cancha` >= 0) and (`monto_descuento` >= 0) and (`monto_descuento` <= `monto_cancha`))),
  CONSTRAINT `ck_reserva_rango` CHECK ((`inicio` < `fin`))
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
